cla4 block12 (.a(a[51:48]),  .b(b[51:48]),  .cin(c[12]), .sum(sum[51:48]), .cout(d[12]), .p0(p[48]), .p1(p[49]), .p2(p[50]), .p3(p[51]), .g0(g_[48]), .g1(g_[49]), .g2(g_[50]), .g3(g_[51]));
