genvar i;
generate
  for (i=0;i<16;i=i+1) begin : gen_gblk
    and #(2)(t1,g_[(4*i)+3]);
    and #(2)(t2,p[(4*i)+3],g_[(4*i)+2]);
    and #(2)(t3,p[(4*i)+3],p[(4*i)+2],g_[(4*i)+1]);
    and #(2)(t4,p[(4*i)+3],p[(4*i)+2],p[(4*i)+1],g_[(4*i)]);
    or #(2)(g[i],t1,t2,t3,t4);
  end
endgenerate
// pblk_0
and #(2) (pblk[0], p[0], p[1], p[2], p[3], cin);


// pblk_1
wire c1_1, c1_2;

and #(2) (c1_1, p[4], p[5], p[6], p[7], g[0]);
